import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import './App.css';
import {  Button } from 'react-bootstrap';
import { Dashboard as MoreVertIcon,} from '@mui/icons-material';
import 'bootstrap/dist/css/bootstrap.min.css';
import { useNavigate } from 'react-router-dom';
import AdminSidebar from './AdminSidebar';
// import { appConfig } from "./config";

const ProductAdmin = () => {
  const [isMobile, setIsMobile] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const {selectedUserType} = useParams();
  const [productData, setProductData] = useState(null);
  const [imageUrls, setImageUrls] = useState([]);
  const [productType, setProductType] = useState("Approved");
  const [comments, setComments] = useState("");
  const { id } = useParams();
  const navigate = useNavigate(); 
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch(`https://handymanapiv15-cmhuc3b9fcd0eeb9.canadacentral-01.azurewebsites.net/api/Product/${id}`);
        const data = await response.json();
        setProductData(data);
        const imageRequests =
          data.productPhotos?.map((photo) =>
            fetch(
              `https://handymanapiv15-cmhuc3b9fcd0eeb9.canadacentral-01.azurewebsites.net/api/FileUpload/download?generatedfilename=${photo}`
            )
              .then((res) => res.json())
              .then((data) => ({
                src: photo,
                imageData: data.imageData,
              }))
          ) || [];
        const images = await Promise.all(imageRequests);
        setImageUrls(images);
      } catch (error) {
        console.error("Error fetching product data:", error);
      }
    };
    fetchData();
  }, [id]);

  // Detect screen size for responsiveness
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    handleResize(); 
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []); 

  const handleSubmit = async () => {
    if (!productData) {
      console.error("No product data to submit.");
      return;
    }
    const payload = {
      ...productData,
      productStatus: productType,
      comments,
      deliveryInDays,
      numberOfStockAvailable,
    };
    try {
      const response = await fetch(`https://handymanapiv15-cmhuc3b9fcd0eeb9.canadacentral-01.azurewebsites.net/api/Product/${id}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });
      if (response.ok) {
        alert("Product status updated successfully.");
        navigate(`/adminProductList/Admin`);
      } else {
        const errorData = await response.json();
        console.error("Error updating product:", errorData);
        alert("Failed to update product. Please try again.");
      }
    } catch (error) {
      console.error("Error submitting product data:", error);
      alert("An error occurred. Please try again later.");
    }
  };

  if (!productData) {
    return (
      <div className="d-flex justify-content-center align-items-center vh-100">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Loading...</span>
        </div>
      </div>
    );
  }

  const {
    productName,
    category,
    catalogue,
    productSize,
    color,
    units,
    rate,
    discount,
    specifications,
    specificationDesc,
    warranty,
    additionalInformation,
    deliveryInDays,
    numberOfStockAvailable,
  } = productData;

  const afterDiscountPrice = rate - (rate * discount) / 100;

  return (
        <div className="d-flex flex-row justify-content-start align-items-start mt-mob-50">
          {/* Sidebar */}
          {!isMobile && (
          <div className="ml-0 m-4 p-0 adm_mnu">
          <AdminSidebar userType={selectedUserType}/>
         </div>
          )}
          {/* Floating menu for mobile */}
      {isMobile && (
        <div className="floating-menu">
          <Button
            variant="primary"
            className="rounded-circle shadow"
            onClick={() => setShowMenu(!showMenu)}
          >
            <MoreVertIcon />
          </Button>
          {showMenu && (
              <div className="sidebar-container">
                <AdminSidebar userType={selectedUserType} />
              </div>
          )}
        </div>
      )}
          {/* Main Content */}
          <div className={`container m-3 ${isMobile ? 'w-100' : 'w-75'}`}>
          <div className=" col-md-11">
            <div className="bg-white p-4 rounded shadow-sm">
              <h3 className="mb-4 text-primary">Product Details</h3>
              {/* Carousel */}
              <div
                id="productCarousel"
                className="carousel slide mb-4 rounded"
                data-bs-ride="carousel"
              >
                {/* Indicators */}
                <div className="carousel-indicators">
                  {imageUrls.map((_, index) => (
                    <button
                      type="button"
                      data-bs-target="#productCarousel"
                      data-bs-slide-to={index}
                      className={index === 0 ? 'active' : ''}
                      aria-current={index === 0 ? 'true' : 'false'}
                      aria-label={`Slide ${index + 1}`}
                      key={index}
                    ></button>
                  ))}
                </div>
                {/* Carousel items */}
                <div className="carousel-inner">
                  {imageUrls.map((img, index) => (
                    <div
                      className={`carousel-item ${index === 0 ? 'active' : ''}`}
                      key={img.src}
                    >
                      <img
                        src={`data:image/jpeg;base64,${img.imageData}`}
                        className="d-block mx-auto rounded"
                        style={{ maxHeight: '500px', width: '50%', objectFit: 'cover' }}
                        alt={`Slide ${index + 1}`}
                      />
                    </div>
                  ))}
                </div>
                {/* Controls */}
                <button
                className="carousel-control-prev"
                type="button"
                data-bs-target="#productCarousel"
                data-bs-slide="prev"
              >
                <span
                  className="carousel-control-prev-icon"
                  aria-hidden="true"
                  style={{ filter: "invert(27%) sepia(98%) saturate(2000%) hue-rotate(200deg) brightness(95%) contrast(90%)" }}
                ></span>
                <span className="visually-hidden">Previous</span>
              </button>

              <button
                className="carousel-control-next"
                type="button"
                data-bs-target="#productCarousel"
                data-bs-slide="next"
              >
                <span
                  className="carousel-control-next-icon"
                  aria-hidden="true"
                  style={{ filter: "invert(27%) sepia(98%) saturate(2000%) hue-rotate(200deg) brightness(95%) contrast(90%)" }}
                ></span>
                <span className="visually-hidden">Next</span>
              </button>

              </div>
              {/* Product Details */}
              <div className="row">
                <div className="col-md-6">
                  <p><strong>Category:</strong> {category}</p>
                  <p><strong>Name:</strong> {productName}</p>
                  <p><strong>Catalogue:</strong> {catalogue}</p>
                  <p><strong>Size:</strong> {productSize}</p>
                  <p><strong>Color:</strong> {color}</p>
                  <p><strong>Units:</strong> {units}</p>
                  <p><strong>Rate:</strong> Rs {rate}</p>
                  <p><strong>Discount:</strong> {discount}%</p>
                  <p><strong>Price After Discount:</strong> Rs {afterDiscountPrice.toFixed(0)}</p>
                 <p><strong>Warranty:</strong> {warranty}</p>
                  <p><strong>Additional Information:</strong> {additionalInformation}</p>
                  <p><strong>Delivery In Days:</strong> {deliveryInDays}</p>
                  <p><strong>Stock Left:</strong> {numberOfStockAvailable}</p></div>
                <div className="col-md-6">
                  <h5>Specifications</h5>
                  <ul>
                    {specifications?.map((spec, index) => (
                      <li key={index}>
                        {spec.label}: {spec.value}
                      </li>
                    ))}
                    <li>{specificationDesc}</li>
                  </ul>
                 
                </div> 
              </div>    
               {/* Approval Section */}
               <div className="">
                  <h5>Approval</h5>
                  <div className="form-check">
                    <input
                      type="radio"
                      className="form-check-input"
                      name="productStatus"
                      id="approve"
                      value="Approved"
                      checked={productType === 'Approved'}
                      onChange={() => setProductType('Approved')}
                    />
                    <label className="form-check-label" htmlFor="approve">Approve</label>
                  </div>
                  <div className="form-check">
                    <input
                      type="radio"
                      className="form-check-input"
                      name="productStatus"
                      id="reject"
                      value="Reject"
                      checked={productType === 'Reject'}
                      onChange={() => setProductType('Reject')}
                    />
                    <label className="form-check-label" htmlFor="reject">Reject</label>
                  </div>
                  <textarea
                    className="form-control"
                    placeholder="Comments"
                    value={comments}
                    onChange={(e) => setComments(e.target.value)}
                  />
                </div>
                {/* Submit Button */}
                <div>
                  <button className="btn btn-primary m-1" onClick={handleSubmit}>
                    Submit
                  </button>
                  <button
        type="button"
        className='btn btn-warning text-white'
          onClick={() => navigate(`/adminProductList/Admin`)}
      >
        <span>Back</span>
      </button>
                </div>
            </div>
          </div>
        </div>
      </div>
  );
};

export default ProductAdmin;
